public long candies(int n, List<Integer> ratings) {
    int[] r = ratings.stream().mapToInt(Integer::intValue).toArray();
    int[] candy = new int[n];
    java.util.Arrays.fill(candy, 1);
    boolean changed = true;
    while (changed) {
        changed = false;
        for (int i = 0; i < n; i++) {
            if (i > 0 && r[i] > r[i - 1] && candy[i] <= candy[i - 1]) {
                candy[i] = candy[i - 1] + 1;
                changed = true;
            }
            if (i < n - 1 && r[i] > r[i + 1] && candy[i] <= candy[i + 1]) {
                candy[i] = candy[i + 1] + 1;
                changed = true;
            }
        }
    }
    long total = 0;
    for (int c : candy) total += c;
    return total;
}

