public long candies(int n, List<Integer> ratings) {
    int[] r = ratings.stream().mapToInt(Integer::intValue).toArray();
    if (n == 0) return 0;
    long total = 1;
    int up = 0, down = 0, peak = 1;
    for (int i = 1; i < n; i++) {
        if (r[i] > r[i - 1]) {
            up++; down = 0; peak = up + 1;
            total += peak;
        } else if (r[i] < r[i - 1]) {
            up = 0; down++;
            total += down + (down >= peak ? 1 : 0);
        } else {
            up = 0; down = 0; peak = 1;
            total += 1;
        }
    }
    return total;
}

